package org.eclipse.kura.internal.rest.identity.provider.test;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertFalse;
import static org.junit.Assert.assertNotNull;
import static org.junit.Assert.assertTrue;
import static org.junit.Assert.fail;

import java.util.Arrays;
import java.util.HashSet;
import java.util.Optional;
import java.util.Set;
import java.util.concurrent.TimeUnit;

import org.eclipse.kura.core.testutil.requesthandler.AbstractRequestHandlerTest;
import org.eclipse.kura.core.testutil.requesthandler.RestTransport;
import org.eclipse.kura.core.testutil.requesthandler.Transport.MethodSpec;
import org.eclipse.kura.crypto.CryptoService;
import org.eclipse.kura.util.wire.test.WireTestUtil;
import org.junit.Test;
import org.osgi.service.useradmin.Group;
import org.osgi.service.useradmin.Role;
import org.osgi.service.useradmin.User;
import org.osgi.service.useradmin.UserAdmin;

/**
 * Feature: an identity holding the rest.identity permission, but not kura.admin, can manage through the Identity REST
 * API v2 only identities and permissions within its own set of permissions.
 */
public class IdentityPermissionManagementTest extends AbstractRequestHandlerTest {

    private static final String ADMIN_PERMISSION = "kura.admin";
    private static final String IDENTITY_PERMISSION = "rest.identity";
    private static final String HELD_PERMISSION = "rest.network.status";
    private static final String NOT_HELD_PERMISSION = "rest.command";

    private static final String MANAGER = "peV2Manager";
    private static final String MANAGER_PASSWORD = "Manager-Passw0rd!";
    private static final String OTHER_ADMIN = "peV2OtherAdmin";
    private static final String PRIVILEGED = "peV2Privileged";
    private static final String UNPRIVILEGED = "peV2Unprivileged";
    private static final String ORIGINAL_PASSWORD = "Original-Passw0rd!";
    private static final String NEW_PASSWORD = "Changed-Passw0rd!1";
    private static final String TEST_PERMISSION = "peV2.test.permission";

    private String originalPasswordHash;

    public IdentityPermissionManagementTest() {
        super(new RestTransport("identity/v2"));
    }

    /*
     * Scenarios
     */

    @Test
    public void nonAdminCannotGrantAdminPermissionToItself() {
        givenRestIdentityManager();

        whenPermissionsAreAssigned(MANAGER, IDENTITY_PERMISSION, ADMIN_PERMISSION);

        thenResponseCodeIs(403);
        thenIdentityDoesNotHavePermission(MANAGER, ADMIN_PERMISSION);
    }

    @Test
    public void nonAdminCannotGrantPermissionItDoesNotHold() {
        givenRestIdentityManager();
        givenIdentity(UNPRIVILEGED, ORIGINAL_PASSWORD);

        whenPermissionsAreAssigned(UNPRIVILEGED, NOT_HELD_PERMISSION);

        thenResponseCodeIs(403);
        thenIdentityDoesNotHavePermission(UNPRIVILEGED, NOT_HELD_PERMISSION);
    }

    @Test
    public void nonAdminCanGrantPermissionItHolds() {
        givenRestIdentityManager();
        givenIdentity(UNPRIVILEGED, ORIGINAL_PASSWORD);

        whenPermissionsAreAssigned(UNPRIVILEGED, HELD_PERMISSION);

        thenRequestSucceeds();
        thenIdentityHasPermission(UNPRIVILEGED, HELD_PERMISSION);
    }

    @Test
    public void nonAdminCannotChangePasswordOfAdminIdentity() {
        givenRestIdentityManager();
        givenIdentity(OTHER_ADMIN, ORIGINAL_PASSWORD, ADMIN_PERMISSION);

        whenPasswordIsChanged(OTHER_ADMIN, NEW_PASSWORD);

        thenResponseCodeIs(403);
        thenPasswordIsUnchanged(OTHER_ADMIN);
    }

    @Test
    public void nonAdminCannotChangePasswordOfMorePrivilegedIdentity() {
        givenRestIdentityManager();
        givenIdentity(PRIVILEGED, ORIGINAL_PASSWORD, NOT_HELD_PERMISSION);

        whenPasswordIsChanged(PRIVILEGED, NEW_PASSWORD);

        thenResponseCodeIs(403);
        thenPasswordIsUnchanged(PRIVILEGED);
    }

    @Test
    public void nonAdminCannotDeleteAdminIdentity() {
        givenRestIdentityManager();
        givenIdentity(OTHER_ADMIN, ORIGINAL_PASSWORD, ADMIN_PERMISSION);

        whenIdentityIsDeleted(OTHER_ADMIN);

        thenResponseCodeIs(403);
        thenIdentityExists(OTHER_ADMIN);
    }

    @Test
    public void nonAdminCannotDeleteMorePrivilegedIdentity() {
        givenRestIdentityManager();
        givenIdentity(PRIVILEGED, ORIGINAL_PASSWORD, NOT_HELD_PERMISSION);

        whenIdentityIsDeleted(PRIVILEGED);

        thenResponseCodeIs(403);
        thenIdentityExists(PRIVILEGED);
    }

    @Test
    public void nonAdminCanDeleteIdentityWithinItsPermissions() {
        givenRestIdentityManager();
        givenIdentity(UNPRIVILEGED, ORIGINAL_PASSWORD, HELD_PERMISSION);

        whenIdentityIsDeleted(UNPRIVILEGED);

        thenRequestSucceeds();
        thenIdentityDoesNotExist(UNPRIVILEGED);
    }

    @Test
    public void nonAdminCannotCreatePermission() {
        givenRestIdentityManager();

        whenRequestIsPerformed(new MethodSpec("POST"), "/permissions", "{\"name\":\"" + TEST_PERMISSION + "\"}");

        thenResponseCodeIs(403);
        thenPermissionDoesNotExist(TEST_PERMISSION);
    }

    @Test
    public void nonAdminCannotDeleteAdminPermission() {
        givenRestIdentityManager();

        whenRequestIsPerformed(new MethodSpec("DELETE", "DEL"), "/permissions",
                "{\"name\":\"" + ADMIN_PERMISSION + "\"}");

        thenResponseCodeIs(403);
        thenPermissionExists(ADMIN_PERMISSION);
    }

    @Test
    public void adminCanGrantAdminPermission() {
        givenAdminCredentials();
        givenIdentity(UNPRIVILEGED, ORIGINAL_PASSWORD);

        whenPermissionsAreAssigned(UNPRIVILEGED, ADMIN_PERMISSION);

        thenRequestSucceeds();
        thenIdentityHasPermission(UNPRIVILEGED, ADMIN_PERMISSION);
    }

    /*
     * Steps
     */

    /*
     * Given
     */

    private void givenRestIdentityManager() {
        givenIdentity(MANAGER, MANAGER_PASSWORD, IDENTITY_PERMISSION, HELD_PERMISSION);
        ((RestTransport) this.transport).setBasicCredentials(Optional.of(MANAGER + ":" + MANAGER_PASSWORD));
    }

    private void givenAdminCredentials() {
        ((RestTransport) this.transport).setBasicCredentials(Optional.of("admin:admin"));
    }

    private void givenIdentity(final String name, final String password, final String... permissions) {
        final UserAdmin userAdmin = userAdmin();

        userAdmin.removeRole("kura.user." + name);
        final User user = (User) userAdmin.createRole("kura.user." + name, Role.USER);

        try {
            final String hash = cryptoService().sha256Hash(password);
            user.getCredentials().put("kura.password", hash);
            this.originalPasswordHash = hash;
        } catch (final Exception e) {
            fail("failed to compute password hash: " + e.getMessage());
        }

        for (final String permission : permissions) {
            getOrCreatePermission(userAdmin, permission).addMember(user);
        }
    }

    /*
     * When
     */

    private void whenPermissionsAreAssigned(final String identity, final String... permissions) {
        final StringBuilder permissionsJson = new StringBuilder();
        for (final String permission : permissions) {
            if (permissionsJson.length() > 0) {
                permissionsJson.append(',');
            }
            permissionsJson.append("{\"name\":\"").append(permission).append("\"}");
        }

        whenRequestIsPerformed(new MethodSpec("PUT"), "/identities", "{\"identity\":{\"name\":\"" + identity
                + "\"},\"permissionConfiguration\":{\"permissions\":[" + permissionsJson + "]}}");
    }

    private void whenPasswordIsChanged(final String identity, final String password) {
        whenRequestIsPerformed(new MethodSpec("PUT"), "/identities",
                "{\"identity\":{\"name\":\"" + identity + "\"},\"passwordConfiguration\":{"
                        + "\"passwordAuthEnabled\":true,\"passwordChangeNeeded\":false,\"password\":\"" + password
                        + "\"}}");
    }

    private void whenIdentityIsDeleted(final String identity) {
        whenRequestIsPerformed(new MethodSpec("DELETE", "DEL"), "/identities", "{\"name\":\"" + identity + "\"}");
    }

    /*
     * Then
     */

    private void thenIdentityHasPermission(final String identity, final String permission) {
        assertTrue(identity + " should have " + permission, permissionsOf(identity).contains(permission));
    }

    private void thenIdentityDoesNotHavePermission(final String identity, final String permission) {
        assertFalse(identity + " must not have " + permission, permissionsOf(identity).contains(permission));
    }

    private void thenPasswordIsUnchanged(final String identity) {
        final Role role = userAdmin().getRole("kura.user." + identity);
        assertNotNull(identity + " should exist", role);
        assertEquals(this.originalPasswordHash, ((User) role).getCredentials().get("kura.password"));
    }

    private void thenIdentityExists(final String identity) {
        assertTrue(identity + " should exist", userAdmin().getRole("kura.user." + identity) instanceof User);
    }

    private void thenIdentityDoesNotExist(final String identity) {
        assertFalse(identity + " should not exist", userAdmin().getRole("kura.user." + identity) instanceof User);
    }

    private void thenPermissionExists(final String permission) {
        assertTrue(permission + " should exist",
                userAdmin().getRole("kura.permission." + permission) instanceof Group);
    }

    private void thenPermissionDoesNotExist(final String permission) {
        assertFalse(permission + " should not exist",
                userAdmin().getRole("kura.permission." + permission) instanceof Group);
    }

    /*
     * Utilities
     */

    private static Set<String> permissionsOf(final String identity) {
        final UserAdmin userAdmin = userAdmin();
        final String userRoleName = "kura.user." + identity;
        final Set<String> result = new HashSet<>();

        try {
            final Role[] roles = userAdmin.getRoles(null);
            for (final Role permission : roles == null ? new Role[0] : roles) {
                if (!(permission instanceof Group) || !permission.getName().startsWith("kura.permission.")) {
                    continue;
                }
                final Role[] members = ((Group) permission).getMembers();
                if (members != null && Arrays.stream(members).anyMatch(m -> userRoleName.equals(m.getName()))) {
                    result.add(permission.getName().substring("kura.permission.".length()));
                }
            }
        } catch (final Exception e) {
            fail("failed to retrieve permissions: " + e.getMessage());
        }

        return result;
    }

    private static Group getOrCreatePermission(final UserAdmin userAdmin, final String permission) {
        final Role role = userAdmin.getRole("kura.permission." + permission);

        if (role instanceof Group) {
            return (Group) role;
        }

        return (Group) userAdmin.createRole("kura.permission." + permission, Role.GROUP);
    }

    private static UserAdmin userAdmin() {
        return trackService(UserAdmin.class);
    }

    private static CryptoService cryptoService() {
        return trackService(CryptoService.class);
    }

    private static <T> T trackService(final Class<T> classz) {
        try {
            return WireTestUtil.trackService(classz, Optional.empty()).get(30, TimeUnit.SECONDS);
        } catch (final Exception e) {
            fail("failed to track " + classz.getSimpleName());
            throw new IllegalStateException("unreachable");
        }
    }
}
